// Тема приходит в теле POST-запроса параметром topic.
// Узел готовит из неё промпт и проверяет, что тема вообще пришла:
// пустой запрос иначе дошёл бы до модели и стоил денег впустую.
const body = $input.first().json.body ?? $input.first().json;
const topic = (body.topic ?? '').toString().trim();
if (!topic) {
  throw new Error('В запросе нет параметра topic');
}
const style = (body.style ?? '').toString().trim();
const task = style
  ? `Напиши пост для Telegram-канала на тему: ${topic}. Стиль: ${style}.`
  : `Напиши пост для Telegram-канала на тему: ${topic}.`;
return [{ json: { topic, style, task } }];

// Ответ модели лежит во вложенной структуре — добираемся по индексу [0],
// как того требует задание. Разные версии узла кладут текст по-разному,
// поэтому проверяем оба места, прежде чем сдаваться.
const out = $input.first().json;
let text = out?.message?.content
        ?? out?.choices?.[0]?.message?.content
        ?? out?.content
        ?? '';
text = text.toString().trim();
if (!text) {
  throw new Error('Модель вернула пустой текст: ' + JSON.stringify(out).slice(0, 300));
}
// Telegram режет сообщения длиннее 4096 символов — обрезаем заранее,
// иначе публикация упадёт уже на стороне Telegram.
if (text.length > 4000) { text = text.slice(0, 3997) + '...'; }
const topic = $('Prepare Prompt').first().json.topic;
return [{ json: { topic, text, length: text.length } }];

